sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_fps;
uniform float amzp_seed;
uniform float amzp_grain;
uniform float amzp_grainSize;
uniform float amzp_dust;
uniform float amzp_dustSize;
uniform float amzp_whiteDust;
uniform float amzp_scratches;
uniform float amzp_scratchWidth;
uniform float amzp_scratchLife;
uniform float amzp_hair;
uniform float amzp_flicker;
uniform float amzp_weave;
uniform float amzp_blotch;
uniform float amzp_vignette;
layout(color) uniform half4 amzp_tint;
uniform float amzp_tintAmt;
uniform float amzp_fade;
uniform float amzp_desat;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float fr;
    float h1(float x) { return fract(sin(x * 91.345 + amzp_seed * 13.7) * 43758.5453); }
    float h2(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 3.91 + fr * 17.13) * 43758.5453); }
    float vn(float2 p) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(h2(i), h2(i + float2(1.0, 0.0)), f.x), mix(h2(i + float2(0.0, 1.0)), h2(i + float2(1.0, 1.0)), f.x), f.y);
    }
    void nmFxMain() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float2 p = uv * W;
        float px = pxs();
        fr = floor(time * max(amzp_fps, 1.0));
        float U = min(W.x, W.y);
        float2 wv = (float2(h1(fr * 1.7), h1(fr * 2.3 + 5.0)) - 0.5) * 2.0 * amzp_weave * px;
        float2 suv = clamp((p - wv) / W, 0.0, 1.0);
        float4 c = amzTexture(0, l2s(suv));
        float3 u = c.a > 0.0001 ? c.rgb / c.a : float3(0.0);
        float l = dot(u, float3(0.299, 0.587, 0.114));
        u = mix(u, float3(l), clamp(amzp_desat, 0.0, 1.0));
        u = mix(u, u * amzp_tint.rgb * 1.15 + amzp_tint.rgb * 0.05, clamp(amzp_tintAmt, 0.0, 1.0));
        u = mix(u, u * 0.8 + 0.12, clamp(amzp_fade, 0.0, 1.0));
        u *= 1.0 + (h1(fr * 3.1 + 11.0) - 0.5) * 0.5 * amzp_flicker;
        if (amzp_blotch > 0.0) {
            float bn = vn(p / (U * 0.12) + fr * 0.37);
            float bd = smoothstep(0.78, 0.95, bn) * amzp_blotch;
            u = mix(u, u * float3(0.55, 0.42, 0.3), bd);
        }
        float gs = max(amzp_grainSize, 0.5) * px;
        float g = vn(p / gs) + vn(p / (gs * 0.5) + 7.0) * 0.5 - 0.75;
        u += g * 0.25 * amzp_grain;
        if (amzp_dust > 0.0) {
            float ds = max(amzp_dustSize, 0.5) * px;
            float2 cellSz = float2(ds * 12.0);
            float2 ci = floor(p / cellSz);
            for (int j = 0; j < 4; j++) {
                float2 cc = ci + float2(float(j - (j / 2) * 2), float(j / 2)) - 0.5 + step(0.5, fract(p / cellSz)) - 0.5;
                cc = floor(cc + 0.5);
                if (h2(cc + 3.3) > amzp_dust * 0.35) continue;
                float2 sp = (cc + float2(h2(cc + 1.1), h2(cc + 2.2))) * cellSz;
                float rr = ds * (0.4 + h2(cc + 4.4));
                float2 dq = (p - sp) / rr;
                dq.x *= 0.6 + h2(cc + 5.5) * 0.8;
                float m = 1.0 - smoothstep(0.6, 1.0, length(dq) + (vn(dq * 2.0 + cc) - 0.5) * 0.5);
                bool white = h2(cc + 6.6) < amzp_whiteDust;
                u = mix(u, white ? float3(0.95) : float3(0.04), m * 0.9);
            }
        }
        if (amzp_scratches > 0.0) {
            float life = max(amzp_scratchLife, 1.0);
            for (int k = 0; k < 6; k++) {
                float fk = float(k);
                if (fk >= 1.0 + amzp_scratches * 5.0) break;
                float gen = floor((fr + fk * 7.0) / life);
                float sx = h1(gen * 13.1 + fk * 3.7) * W.x;
                float age = mod(fr + fk * 7.0, life) / life;
                sx += (h1(gen * 5.3 + fk) - 0.5) * 40.0 * px * age;
                float wob = (vn(float2(p.y / (U * 0.1), gen + fk * 9.0)) - 0.5) * 3.0 * px;
                float w = max(amzp_scratchWidth, 0.5) * px;
                float d = abs(p.x - sx - wob);
                float m = (1.0 - smoothstep(w * 0.5, w * 0.5 + px, d)) * (0.5 + 0.5 * vn(float2(p.y / (U * 0.05), gen)));
                bool bright = h1(gen * 2.9 + fk) > 0.5;
                if (h1(gen * 7.7 + fk * 1.3) < amzp_scratches) u = mix(u, bright ? float3(0.92) : float3(0.08), m * 0.8);
            }
        }
        if (amzp_hair > 0.0 && h1(floor(fr / 6.0) * 4.1) < amzp_hair) {
            float hg = floor(fr / 6.0);
            float2 hc = float2(h1(hg * 1.3), h1(hg * 2.7)) * W;
            float2 q = (p - hc) / (U * 0.08);
            float best = 9.0;
            float2 prev = float2(0.0);
            for (int j = 1; j <= 16; j++) {
                float t = float(j) / 16.0;
                float2 cur = float2(t * 2.0 - 1.0, sin(t * 7.0 + hg) * 0.35 + sin(t * 17.0 + hg * 2.0) * 0.12);
                cur = float2(cur.x * cos(hg) - cur.y * sin(hg), cur.x * sin(hg) + cur.y * cos(hg));
                float2 ab = cur - prev;
                float tt = clamp(dot(q - prev, ab) / max(dot(ab, ab), 1e-6), 0.0, 1.0);
                best = min(best, length(q - prev - ab * tt));
                prev = cur;
            }
            float m = 1.0 - smoothstep(0.004, 0.02, best);
            u = mix(u, float3(0.05), m * 0.85);
        }
        float2 vq = (uv - 0.5) * float2(W.x / U, W.y / U);
        u *= 1.0 - clamp(amzp_vignette, 0.0, 1.0) * smoothstep(0.3, 0.95, length(vq));
        u = clamp(u, 0.0, 1.0);
        amzOutput = float4(u * c.a, c.a);
    }
    void amzRender() {
        nmFxMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
